import json
n=28
g=[[0]*n for _ in range(n)]
for i in [4,9,14,19,24]:
    for j in range(n): g[i][j]=8; g[j][i]=8
rb=[(0,4),(5,9),(10,14),(15,19),(20,24),(25,28)]
cb=rb
# fill 2 horizontal row band 1, col bands 0-4
for c in range(0,5):
    for r in range(*rb[1]):
        for j in range(*cb[c]): g[r][j]=2
# 2 vertical colband0, rowbands 1..3
for rband in range(1,4):
    for r in range(*rb[rband]):
        for j in range(*cb[0]): g[r][j]=2
# 3 vertical colband2 rowbands 0..4
for rband in range(0,5):
    for r in range(*rb[rband]):
        for j in range(*cb[2]): g[r][j]=3 if g[r][j]==0 else (6 if g[r][j]==2 else g[r][j])
print(json.dumps(g))
